Top 10 Trusts with highest breach rate                                                                                                                                                                                                                                                                                                  SELECT Name,Breach_Rate                                                                                                                                               FROM breach_data                                                                                                                                                      ORDER BY Breach_Rate DESC                                                                                                                                             LIMIT 10;
Average breach rates across all Trusts                                                                                                                                SELECT ROUND(AVG(Breach_Rate),4)AS avg_breach_rate                                                                                                                    FROM Breach_data;
Trusts where over half of patients breached                                                                                                                           SELECT COUNT(*)AS Trusts_over_50pct                                                                                                                                   FROM breach_data                                                                                                                                                      WHERE Breach_Rate>0.5:                                                                                                                                                    
